const html = "<!doctype html>\n<html lang=\"tr\">\n<head>\n<meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<meta name=\"theme-color\" content=\"#f8f5ef\"><meta name=\"description\" content=\"Nudgy, kaydettiğin içerikleri ve RSS akışlarını Slack’te yeniden karşına çıkaran küçük yardımcın.\"><title>Nudgy — Sonra okurum, artık gerçekten sonra.</title>\n<link rel=\"icon\" href=\"nudgy.webp\" type=\"image/webp\">\n<style>\n@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;450;500;550;600;650;700&family=Manrope:wght@400;500;600;650;700;750;800&display=swap');\n:root{--paper:#f8f5ef;--ink:#332b28;--muted:#7b716a;--orange:#e45c38;--line:#e5dfd6;--peach:#f4e5d5}*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:90px}body{margin:0;color:var(--ink);background:var(--paper);font-family:'DM Sans',sans-serif;font-size:16px}a{color:inherit;text-decoration:none}button{font:inherit;cursor:pointer}button,a{-webkit-tap-highlight-color:transparent}a:focus-visible,button:focus-visible,summary:focus-visible{outline:3px solid var(--orange);outline-offset:5px}.wrap{max-width:1180px;margin:auto;padding:0 38px}header{border-bottom:1px solid var(--line)}nav{height:92px;display:flex;align-items:center;justify-content:space-between}.logo{font-family:Manrope,sans-serif;font-weight:800;font-size:31px;letter-spacing:-1.6px;display:flex;align-items:center;gap:8px}.logo img{width:41px;height:41px;object-fit:contain}.nav-links{display:flex;gap:32px;font-size:13px}.nav-action{border:1px solid #c9bfb4;border-radius:7px;padding:12px 18px;font-weight:600;font-size:13px}.nav-action span{margin-left:16px}.hero{display:grid;grid-template-columns:1.12fr 1fr;gap:25px;padding-top:76px;padding-bottom:69px;align-items:center}.eyebrow{font-size:11px;font-weight:700;letter-spacing:1.7px;text-transform:uppercase;display:flex;align-items:center;gap:9px}.eyebrow i{width:7px;height:7px;border-radius:100%;background:var(--orange)}h1,h2,h3{font-family:Manrope,sans-serif}h1{font-size:62px;letter-spacing:-3.5px;line-height:1.11;margin:25px 0 24px;font-weight:750}h1 em{font-style:normal;color:var(--orange)}.hero-copy>p{max-width:410px;color:var(--muted);line-height:1.75;font-size:16px}.actions{display:flex;align-items:center;gap:25px;margin-top:29px}.primary{display:inline-flex;align-items:center;gap:27px;background:var(--ink);color:white;border:0;border-radius:7px;padding:16px 21px;font-size:13px;font-weight:600}.text-link{font-size:13px;font-weight:600;border-bottom:1px solid #b7aaa0;padding-bottom:4px}.hero-note{display:block;margin-top:17px;font-size:11px;color:#93877c}.hero-art{position:relative;height:445px;display:flex;justify-content:center;align-items:center}.orb{position:absolute;width:380px;height:380px;border-radius:50%;background:#f1e6d7;top:37px;left:50%;transform:translateX(-50%)}.orb:after{content:'';position:absolute;inset:-20px;border:1px dashed #d7c6b4;border-radius:50%}.mascot{width:325px;position:relative;z-index:2;transform:rotate(-7deg);filter:drop-shadow(0 22px 15px #8f543921)}.hello{position:absolute;right:4px;top:9px;background:#fffdf8;border:1px solid var(--line);padding:14px 18px;border-radius:14px 14px 14px 2px;transform:rotate(6deg);font-size:13px;z-index:4}.float-card{position:absolute;background:#fffdf9;z-index:3;border:1px solid #e6dcd0;box-shadow:0 8px 20px #48351d08;border-radius:10px;padding:15px 17px;display:flex;gap:11px;align-items:center;font-size:12px}.float-card strong{display:block;font-size:12px;font-weight:650;margin-bottom:5px}.float-card small{font-size:10px;color:var(--muted)}.float-card .symbol{width:32px;height:32px;display:grid;place-items:center;background:#f4ece1;border-radius:8px;color:var(--orange);font-size:18px}.saved{left:-15px;top:95px;transform:rotate(-7deg)}.digest{right:-15px;bottom:53px;transform:rotate(5deg)}.art-foot{position:absolute;bottom:1px;left:35%;color:#a1836d;font-size:11px;transform:rotate(-5deg)}.star{position:absolute;left:30px;bottom:65px;font-size:45px;color:#c99961;transform:rotate(12deg)}.integrations{border-top:1px solid var(--line);border-bottom:1px solid var(--line);padding:25px 0;display:flex;justify-content:center;align-items:center;gap:45px}.integrations>span{font-size:11px;color:var(--muted);margin-right:14px}.integration{font-family:Manrope,sans-serif;font-weight:750;font-size:19px;letter-spacing:-.6px;display:flex;align-items:center;gap:9px}.integration b{font-size:23px;font-weight:700;color:#7b7269}.section{padding:82px 0}.section-label{font-size:10px;text-transform:uppercase;letter-spacing:2px;color:var(--orange);font-weight:700}.section h2{font-size:37px;letter-spacing:-1.7px;line-height:1.25;margin:14px 0 17px;font-weight:650}.section-intro{font-size:14px;line-height:1.8;color:var(--muted);max-width:430px}.center{text-align:center}.center .section-intro{margin:0 auto}.features{display:grid;grid-template-columns:repeat(3,1fr);margin-top:40px;gap:32px}.feature{border-top:1px solid #d7ccc0;padding-top:25px}.feature-top{display:flex;justify-content:space-between;align-items:center}.feature-number{font-size:11px;color:#998d81}.feature-icon{font-size:25px;color:#bb6d46}.feature h3{font-size:19px;letter-spacing:-.5px;margin:23px 0 12px;font-weight:650}.feature p{font-size:13px;line-height:1.85;color:var(--muted);margin:0;max-width:290px}.demo-section{background:#eee9e1;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}.demo-layout{display:grid;grid-template-columns:.85fr 1.15fr;gap:70px;align-items:center}.demo-copy h2{font-size:40px}.demo-tabs{display:flex;gap:9px;flex-wrap:wrap;margin-top:25px}.demo-tabs button{border:1px solid #d5ccc0;border-radius:6px;padding:10px 13px;background:transparent;font-size:11px;color:#6d6259}.demo-tabs button[aria-pressed=true]{background:var(--ink);color:#fff;border-color:var(--ink)}.chat{background:#fffdfa;border:1px solid #dfd6cb;border-radius:12px;box-shadow:0 16px 35px #48351d08;overflow:hidden}.chat-head{display:flex;align-items:center;gap:10px;padding:15px 20px;border-bottom:1px solid #eee8df;font-size:14px;font-weight:700}.chat-head img{height:32px;width:32px;background:#f6e7d7;border-radius:7px}.chat-head small{margin-left:auto;font-size:9px;letter-spacing:1.2px;color:#a09589;font-weight:500}.chat-body{padding:23px;min-height:292px}.message{display:flex;gap:11px;margin-bottom:24px;font-size:12px;line-height:1.8}.avatar{flex:0 0 32px;width:32px;height:32px;border-radius:6px;background:#e7e9e0;display:grid;place-items:center;font-size:12px}.avatar img{width:32px;height:32px}.message strong{font-size:12px;margin-right:7px}.message time{font-size:9px;color:#a2978c}.message p{margin:3px 0 0}.mention{color:#43718d;background:#edf2f4;padding:1px 3px}.reply-body{white-space:pre-line}.message .bot{background:#f6e7d7}.chat-input{margin:0 20px 18px;border:1px solid #e6dfd5;border-radius:6px;padding:12px 13px;display:flex;justify-content:space-between;font-size:11px;color:#aaa096}.chat-caption{font-size:10px;color:#9a8b7c;text-align:right;margin:12px 0 0}.steps{display:grid;grid-template-columns:repeat(3,1fr);gap:45px;margin-top:40px}.step{display:grid;grid-template-columns:35px 1fr;gap:14px}.step>span{height:32px;width:32px;display:grid;place-items:center;border:1px solid #d7cdc0;border-radius:50%;font-size:11px}.step h3{font-size:15px;margin:5px 0 10px}.step p{font-size:12px;color:var(--muted);line-height:1.8;margin:0}.faq{max-width:760px;margin:0 auto;padding-top:0}.faq h2{font-size:28px;margin-bottom:27px}.faq details{border-top:1px solid var(--line);padding:19px 0}.faq details:last-child{border-bottom:1px solid var(--line)}.faq summary{cursor:pointer;font-size:13px;font-weight:600;list-style:none;display:flex;justify-content:space-between;gap:18px}.faq summary:after{content:'+';color:var(--orange);font-size:17px}.faq details[open] summary:after{content:'−'}.faq details p{font-size:13px;line-height:1.8;color:var(--muted);max-width:640px}.closing{display:flex;align-items:center;justify-content:space-between;padding:38px 50px;background:#efddc8;border-radius:12px;margin-bottom:50px;gap:25px}.closing h2{font-size:29px;letter-spacing:-1px;margin:0 0 10px}.closing p{font-size:13px;color:#89715d;margin:0}.closing .primary{white-space:nowrap}.closing img{width:100px;height:100px;transform:rotate(10deg)}footer{display:flex;justify-content:space-between;align-items:center;border-top:1px solid var(--line);padding:27px 0 30px;font-size:11px;color:#928579}footer .logo{font-size:23px;color:var(--ink)}footer .logo img{height:31px;width:31px}.footer-right{display:flex;gap:25px}dialog{width:min(480px,calc(100% - 32px));background:var(--paper);border:1px solid var(--line);border-radius:15px;padding:32px;color:var(--ink);box-shadow:0 20px 90px #332b2830}dialog::backdrop{background:#332b2866;backdrop-filter:blur(4px)}dialog h2{font-size:25px;letter-spacing:-1px;margin-top:12px}dialog p,dialog li{font-size:13px;line-height:1.9;color:var(--muted)}dialog ol{padding-left:20px}dialog .close{float:right;border:0;background:none;font-size:23px;padding:0 4px}dialog .primary{margin-top:12px}.dialog-mascot{width:70px;height:70px}@media(max-width:1000px){h1{font-size:50px}.hero-art{transform:scale(.88)}.demo-layout{gap:35px}.wrap{padding:0 28px}.closing img{display:none}}@media(max-width:720px){.wrap{padding:0 22px}nav{height:75px}.nav-links{display:none}.logo{font-size:27px}.nav-action{font-size:11px;padding:10px 13px}.hero{grid-template-columns:1fr;padding-top:43px;padding-bottom:30px;gap:15px}h1{font-size:49px;letter-spacing:-2.8px}.hero-copy>p{font-size:15px}.hero-art{height:370px;transform:scale(.9);margin:0 -10px}.orb{height:320px;width:320px;top:25px}.mascot{width:285px}.saved{left:0;top:65px}.digest{right:0;bottom:40px}.hello{right:15px;top:0}.art-foot{bottom:0}.integrations{gap:20px;flex-wrap:wrap;padding:23px 0}.integrations>span{flex-basis:100%;text-align:center;margin:0}.integration{font-size:16px}.section{padding:55px 0}.section h2{font-size:30px}.features{grid-template-columns:1fr;gap:28px}.feature p{max-width:none}.feature h3{margin-top:13px}.demo-layout{grid-template-columns:1fr;gap:30px}.chat-body{padding:19px;min-height:290px}.steps{grid-template-columns:1fr;gap:26px}.faq{padding-top:0}.closing{flex-direction:column;align-items:flex-start;padding:28px;margin-bottom:32px}.closing h2{font-size:26px}.closing p{line-height:1.7}footer{align-items:flex-start;gap:25px}.footer-right{flex-direction:column;gap:12px;text-align:right}.hero-note{font-size:10px}.actions{gap:20px}.primary{padding:15px 17px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}\n</style>\n</head>\n<body id=\"top\">\n<header><nav class=\"wrap\" aria-label=\"Ana menü\"><a class=\"logo\" href=\"#top\"><img src=\"nudgy.webp\" alt=\"\">nudgy<span style=\"color:var(--orange)\">.</span></a><div class=\"nav-links\"><a href=\"#ozellikler\">Neden Nudgy?</a><a href=\"#nasil-calisir\">Nasıl çalışır?</a><a href=\"#sorular\">Merak edilenler</a></div><button class=\"nav-action\" style=\"background:transparent\" data-start>Nudgy ile tanış <span>↗</span></button></nav></header>\n<main>\n<div class=\"wrap\"><section class=\"hero\"><div class=\"hero-copy\"><div class=\"eyebrow\"><i></i> KÜÇÜK BİR DÜRTME. GÜZEL BİR ALIŞKANLIK.</div><h1>“Sonra okurum.”<br>Artık gerçekten<br><em>sonra.</em></h1><p>Kaydettiğin yazılar, biriken RSS akışları…<br>Nudgy onları Slack’te yeniden karşına çıkarır.<br>Sen merak etmeye devam et.</p><div class=\"actions\"><button class=\"primary\" data-start>Nudgy ile tanış <span>↗</span></button><a class=\"text-link\" href=\"#demo\">İş başında gör ↓</a></div><small class=\"hero-note\">Slack’te yaşar. Feedbin ve Raindrop ile çalışır.</small></div><div class=\"hero-art\" aria-label=\"Nudgy, kırmızı ve güler yüzlü küçük yardımcın\"><div class=\"orb\"></div><span class=\"hello\">Psst… bunu kaydetmiştin 👀</span><div class=\"float-card saved\"><span class=\"symbol\">♧</span><div><strong>Sonra okumak üzere.</strong><small>Kaydetmek, sadece başlangıç.</small></div></div><img class=\"mascot\" src=\"nudgy.webp\" alt=\"Meraklı gözlerle yukarı bakan kırmızı Nudgy maskotu\" fetchpriority=\"high\"><div class=\"float-card digest\"><span class=\"symbol\">☷</span><div><strong>Biraz meraka ne dersin?</strong><small>Okuma listene küçük bir dönüş.</small></div></div><span class=\"star\" aria-hidden=\"true\">✳</span><span class=\"art-foot\">senin küçük hatırlatıcın ↗</span></div></section><div class=\"integrations\"><span>ZATEN KULLANDIĞIN YERLERDE</span><div class=\"integration\"><b aria-hidden=\"true\">#</b> Slack</div><div class=\"integration\"><b aria-hidden=\"true\">▤</b> Feedbin</div><div class=\"integration\"><b aria-hidden=\"true\">☁</b> Raindrop.io</div></div>\n<section class=\"section\" id=\"ozellikler\"><div class=\"center\"><span class=\"section-label\">KAYDET. UNUTMA. YENİDEN KEŞFET.</span><h2>İnternet dolu. Kafan dolmasın.</h2><p class=\"section-intro\">İyi bir içeriğe denk gelmek güzel.<br>Ona geri dönebilmek daha da güzel.</p></div><div class=\"features\"><article class=\"feature\"><div class=\"feature-top\"><span class=\"feature-icon\" aria-hidden=\"true\">↗</span><span class=\"feature-number\">01 / HATIRLA</span></div><h3>Kaydettiklerin kaybolmasın.</h3><p>Raindrop’ta biriktirdiğin bağlantılar, Slack’te bir hatırlatmayla yeniden karşına çıksın. “Bir ara” dediğin içeriklere geri dön.</p></article><article class=\"feature\"><div class=\"feature-top\"><span class=\"feature-icon\" aria-hidden=\"true\">☷</span><span class=\"feature-number\">02 / YAKALA</span></div><h3>Akışın özünü yakala.</h3><p>Feedbin’deki RSS akışlarını kısa özetlerle takip et. Nelerin ilgini çektiğine karar ver, okumaya oradan devam et.</p></article><article class=\"feature\"><div class=\"feature-top\"><span class=\"feature-icon\" aria-hidden=\"true\">☏</span><span class=\"feature-number\">03 / SOR</span></div><h3>Bir mesaj kadar yakın.</h3><p>Slack’te Nudgy’ye seslen, içeriklerin hakkında konuş. Yeni bir sekme, yeni bir alışkanlık edinmeden merakının peşinden git.</p></article></div></section></div>\n<section class=\"demo-section\" id=\"demo\"><div class=\"wrap section demo-layout\"><div class=\"demo-copy\"><span class=\"section-label\">BİLDİĞİN YERDE, BİLDİĞİN GİBİ</span><h2>Bir komut öğrenme.<br>Sadece sohbet et.</h2><p class=\"section-intro\">“Bugün neler var?” diye sor. Ya da kaydettiğin içeriklere geri dön. Nudgy, Slack sohbetinin tam içinde.</p><div class=\"demo-tabs\" role=\"group\" aria-label=\"Örnek sohbet seç\"><button aria-pressed=\"true\" data-demo=\"rss\">Günlük özet</button><button aria-pressed=\"false\" data-demo=\"saved\">Kaydettiklerim</button><button aria-pressed=\"false\" data-demo=\"ask\">Biraz daha anlat</button></div></div><div><div class=\"chat\"><div class=\"chat-head\"><img src=\"nudgy.webp\" alt=\"\">Nudgy <small>ÖRNEK SOHBET</small></div><div class=\"chat-body\" aria-live=\"polite\"><div class=\"message\"><span class=\"avatar\">S</span><div><strong>Sen</strong><time>09:41</time><p><span class=\"mention\">@Nudgy</span> <span id=\"prompt\">Bugünkü RSS akışımda neler var?</span></p></div></div><div class=\"message\"><span class=\"avatar bot\"><img src=\"nudgy.webp\" alt=\"\"></span><div><strong>Nudgy</strong><time>09:41</time><p class=\"reply-body\" id=\"reply\">Günaydın! Okuma turuna çıkalım mı? ☀️\n\nBugünkü akışında sakin çalışma alanları, dijital bahçeler ve yaratıcı rutinler var.\n\nHangisinden başlayalım?</p></div></div></div><div class=\"chat-input\"><span>Yukarıdan bir sohbet örneği seç</span><span aria-hidden=\"true\">↵</span></div></div><p class=\"chat-caption\">Tanıtım amaçlı örnek içerik; canlı hesap verisi değildir.</p></div></div></section>\n<div class=\"wrap\"><section class=\"section\" id=\"nasil-calisir\"><div class=\"center\"><span class=\"section-label\">KÜÇÜK BİR BAŞLANGIÇ</span><h2>Merakına yer aç.</h2></div><div class=\"steps\"><article class=\"step\"><span>1</span><div><h3>Slack’te buluşun.</h3><p>Nudgy kurulu çalışma alanında sohbeti aç. Yardımcın zaten bulunduğun yerde olsun.</p></div></article><article class=\"step\"><span>2</span><div><h3>İçeriklerini bağla.</h3><p>Nudgy’nin özel mesajındaki bağlantıyla Feedbin veya Raindrop hesabını bağla.</p></div></article><article class=\"step\"><span>3</span><div><h3>Gerisini sohbete bırak.</h3><p>Özetlerini sor, kaydettiklerini keşfet. Hatırlatmalarla okuma listene geri dön.</p></div></article></div></section><section class=\"section faq\" id=\"sorular\"><h2>Bir de şunları merak etmiş olabilirsin.</h2><details><summary>Nudgy tam olarak ne yapıyor?</summary><p>Nudgy, Slack içinden kullanabileceğin bir içerik yardımcısı. Bağladığın Feedbin hesabındaki RSS içeriklerini özetler, Raindrop bağlantılarını yeniden karşına çıkarır ve bu içerikler hakkında sorularını yanıtlar.</p></details><details><summary>Başlamak için ne gerekiyor?</summary><p>Çalışma alanında Nudgy’nin kurulmuş olması gerekiyor. Ardından Slack’te gelen özel bağlantılarla Feedbin veya Raindrop hesabını bağlayabilirsin. Kurulum ve kullanılabilir entegrasyonlar çalışma alanının yapılandırmasına bağlıdır.</p></details><details><summary>Bu sayfadaki sohbeti gerçekten deneyebilir miyim?</summary><p>Yukarıdaki üç seçenek, Nudgy’nin kullanımını anlatan etkileşimli örnekler. Gerçek içeriklerinle sohbet etmek için Slack’te Nudgy’yi kullanman ve ilgili hesabını bağlaman gerekiyor.</p></details></section><section class=\"closing\"><img src=\"nudgy.webp\" alt=\"\" loading=\"lazy\"><div><h2>Biriken linklere küçük bir dürtme.</h2><p>Kaydettiğin meraka geri dön. Nudgy yanında.</p></div><button class=\"primary\" data-start>Hadi, tanışalım <span>↗</span></button></section><footer><a href=\"#top\" class=\"logo\"><img src=\"nudgy.webp\" alt=\"\">nudgy.</a><span class=\"footer-right\"><span>Meraklı insanlar için, küçük bir yardımcı.</span><a href=\"#top\">Yukarı dön ↑</a></span></footer></div>\n</main>\n<dialog id=\"start-dialog\" aria-labelledby=\"start-title\"><button class=\"close\" aria-label=\"Pencereyi kapat\">×</button><img class=\"dialog-mascot\" src=\"nudgy.webp\" alt=\"\"><h2 id=\"start-title\">Nudgy ile Slack’te buluşalım.</h2><p>Nudgy çalışma alanına kuruluysa başlamak çok kolay:</p><ol><li>Slack’te Nudgy ile özel mesajlarını aç.</li><li>Gelen bağlantı davetinden Feedbin veya Raindrop hesabını bağla.</li><li>Nudgy’yi etiketleyerek “RSS özetimi getir” diye sor.</li></ol><p>Çalışma alanında Nudgy yoksa kurulum için çalışma alanı yöneticinle görüş.</p><button class=\"primary\" id=\"copy-prompt\">İlk mesajı kopyala <span>↗</span></button><p id=\"copy-status\" role=\"status\"></p></dialog>\n<script>\nconst samples={rss:{q:'Bugünkü RSS akışımda neler var?',a:'Günaydın! Okuma turuna çıkalım mı? ☀️\\n\\nBugünkü akışında sakin çalışma alanları, dijital bahçeler ve yaratıcı rutinler var.\\n\\nHangisinden başlayalım?'},saved:{q:'Bu hafta kaydettiğim içerikleri hatırlatır mısın?',a:'Tabii! Okuma listene küçük bir dönüş yapalım. 📚\\n\\nBu hafta yaratıcı rutinler üzerine bir yazı ve dijital not tutma hakkında bir rehber kaydetmişsin.\\n\\nİçlerinden birini birlikte keşfedelim mi?'},ask:{q:'Dijital bahçeler hakkındaki yazıyı biraz anlatır mısın?',a:'Elbette! 🌱\\n\\nYazı, notlarını bitmiş metinler olarak değil, zamanla büyüyen fikirler olarak görmeyi öneriyor. Fikirler arasında bağlantı kurmak da bunun bir parçası.\\n\\nKendi notların için ilham verici bir başlangıç olabilir.'}};\ndocument.querySelectorAll('[data-demo]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-demo]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));document.getElementById('prompt').textContent=samples[b.dataset.demo].q;document.getElementById('reply').textContent=samples[b.dataset.demo].a}));\nconst dialog=document.getElementById('start-dialog');document.querySelectorAll('[data-start]').forEach(b=>b.addEventListener('click',()=>dialog.showModal()));dialog.querySelector('.close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});document.getElementById('copy-prompt').addEventListener('click',async()=>{try{await navigator.clipboard.writeText('@Nudgy RSS özetimi getir');document.getElementById('copy-status').textContent='Kopyalandı! Slack’te Nudgy sohbetine yapıştırabilirsin.'}catch{document.getElementById('copy-status').textContent='Şu mesajı seçip kopyalayabilirsin: @Nudgy RSS özetimi getir'}});\n</script>\n</body>\n</html>\n";
const mascot = Uint8Array.from(atob(""), c => c.charCodeAt(0));
Bun.serve({
  hostname: "0.0.0.0",
  port: Number(Bun.env.PORT || 8080),
  fetch(request) {
    if (!["GET", "HEAD"].includes(request.method)) return new Response("Method not allowed", {status: 405, headers: {Allow: "GET, HEAD"}});
    const path = new URL(request.url).pathname;
    let body, type, cache = "public, max-age=300";
    if (path === "/" || path === "/index.html") { body = html; type = "text/html; charset=utf-8"; }
    else if (path === "/nudgy.webp") { body = mascot; type = "image/webp"; cache = "public, max-age=86400"; }
    else if (path === "/healthz") { body = "ok"; type = "text/plain"; cache = "no-store"; }
    else return new Response(request.method === "HEAD" ? null : "Not found", {status: 404});
    return new Response(request.method === "HEAD" ? null : body, {headers: {"Content-Type": type, "Cache-Control": cache, "X-Content-Type-Options": "nosniff", "Referrer-Policy": "strict-origin-when-cross-origin"}});
  }
});
